package com.drivique.api.model;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="incident_reports",schema="support") public class IncidentReport{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="incident_code",nullable=false,unique=true,length=30) private String incidentCode;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="vehicle_id") private Vehicle vehicle;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reservation_id") private Reservation reservation;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="reported_by_user_id",nullable=false) private User reporter;@Column(nullable=false,length=20) private String status="OPEN";@Column(nullable=false,length=20) private String priority="MEDIUM";@Column(nullable=false,length=150) private String subject;@Column(nullable=false,columnDefinition="text") private String description;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();protected IncidentReport(){}public IncidentReport(String code,Vehicle v,Reservation r,User u,String priority,String subject,String description){incidentCode=code;vehicle=v;reservation=r;reporter=u;this.priority=priority;this.subject=subject;this.description=description;}public UUID getId(){return id;}public User getReporter(){return reporter;}public String getStatus(){return status;}public void setStatus(String v){status=v;updatedAt=Instant.now();}}
